-- A person's grade is dated: each grade they are given applies from its from-date, and a claim uses
-- the one whose from-date is the latest on or before its date. No from-date applies from the
-- beginning of time: the first grade a person was given. The list shows the grade in force on the
-- sheet's today.
CREATE TABLE person_grade (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    grade     VARCHAR(1)   NOT NULL,
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01')),
    set_by    VARCHAR(200) NOT NULL,
    set_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX person_grade_from ON person_grade (person_id, from_key);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by)
    SELECT sheet_id, id, grade, NULL, created_by FROM person;
ALTER TABLE person DROP COLUMN grade;
-- A claim with a negative amount is a correction of a SETTLED claim of the same person: it keeps
-- the number of the claim it corrects (none for any other claim). The amount may now be negative:
-- the column is rebuilt without its old 0-or-more check.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(19, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD COLUMN corrects BIGINT;
-- A claim's number is now text: the sheet-wide number (1, 2, ...) or, while the sheet's
-- period-numbering-from setting is in force when it is opened, <period name>-<n> (X-<n> for a claim
-- in no period). A correction names the number of the claim it corrects in the same form.
ALTER TABLE claim ALTER COLUMN number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
-- The last number given in each period's own sequence on a sheet; the key '' is the sequence of
-- claims in no period. Numbers are never reused, so the sheet keeps them past a claim's voiding.
CREATE TABLE sheet_period_number (
    sheet_id    VARCHAR(200) NOT NULL REFERENCES sheet (id),
    period_key  VARCHAR(200) NOT NULL,
    last_number BIGINT       DEFAULT 0 NOT NULL,
    PRIMARY KEY (sheet_id, period_key)
);
-- A claim's place in its sheet's list, newest first: given when added and again when it is moved to
-- another person (so a moved claim is listed as its new person's newest). Ties fall back to the id.
ALTER TABLE claim ADD COLUMN list_seq BIGINT DEFAULT 0 NOT NULL;
UPDATE claim SET list_seq = id;
-- A claim's due-by, fixed when it is added: its date plus the terms of its person's grade in force on
-- its date (a grade's own terms, setting terms-<grade>, else the sheet's terms). It does not change
-- when the terms or its date change later. Claims already added take their date plus the sheet's
-- terms now (14 when never set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.val AS INT) FROM sheet_setting s
    WHERE s.sheet_id = claim.sheet_id AND s.setting = 'terms'), 14), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A claim's status log: one line per status it has had (DRAFT when it was added, then each change),
-- with who made the change, the sheet's today then, and the claim's due as computed at that moment
-- (none: n/a). Listed oldest first (by id). Claims added before the log have no lines.
CREATE TABLE claim_log (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    status   VARCHAR(10)    NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    due      DECIMAL(19, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
-- A hold is dated: it runs from its from-date to its to-date (none: open-ended), and a person may
-- have several over time. Only a person's OPEN claims dated within a hold count in no live total;
-- a claim bound by a statement still counts whatever its date. A person held before holds were
-- dated keeps a hold from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    from_date DATE         NOT NULL,
    to_date   DATE,
    held_by   VARCHAR(200) NOT NULL,
    held_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_hold_person ON person_hold (sheet_id, person_id, id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_by)
    SELECT sheet_id, id, DATE '0001-01-01', NULL, created_by FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A rate can carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it (the latest from-date on or before its date) has no rate. Null: no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- A closed period's figures per person: each person on the sheet when it was closed, with the due of
-- their claims that count dated in it, fixed at that moment. A person added later has none (0.00).
-- Removed when the period is reopened. The period's due-total is the sum of these.
CREATE TABLE period_person_total (
    period_id BIGINT        NOT NULL REFERENCES period (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    total     DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- The sheet's own "today": every date decision and default date on the sheet uses it, never the
-- real clock. It starts as the real date the sheet is first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE) WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a claim uses
-- the one whose from-date is the latest on or before its date. No from-date applies from the
-- beginning of time (at most one such rate per grade).
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
-- A rate can carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it (the latest from-date on or before its date) has no rate. Null: no end.
ALTER TABLE rate ADD COLUMN to_date DATE;

