package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a change that went through is recorded. */
public class RecordSettingChanged {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Setting setting, Audit audit) {
        audit.record("SETTING_CHANGED sheet=" + setting.sheetId() + " by=" + (by == null ? "" : by)
                + " key=" + setting.key() + " value=" + setting.value());
    }
}
package net.officefloor.hq.app.setting;

/** A sheet setting: its key and its value as text ("" when blank). */
public record Setting(String sheetId, String key, String value) {
}
package net.officefloor.hq.app.setting;

/** Body of changing a setting; a blank value clears it. */
public record SettingRequest(String key, String value) {
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSetting {
    public void respond(@Val Setting setting, ObjectResponse<Setting> response) {
        response.send(setting);
    }
}
