-- A setting that carries a figure is dated: each value saved applies from its from-date, a key may
-- have several (one per from-date), and the value in force on a date is the one with the latest
-- from-date on or before it. No from-date applies from the beginning of time: the values set before
-- settings were dated, and the undated keys (policy-date, period-numbering-from).
ALTER TABLE sheet_setting ADD COLUMN from_date DATE;
ALTER TABLE sheet_setting DROP PRIMARY KEY;
ALTER TABLE sheet_setting ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX sheet_setting_from ON sheet_setting (sheet_id, setting, from_key);
EOF
cat > java/net/officefloor/hq/app/setting/DatedSetting.java <<'EOF'
package net.officefloor.hq.app.setting;

import java.util.List;

/** A dated setting's values by from-date, and the value it has before every from-date ({@code start};
 *  null: none). */
public record DatedSetting(List<Setting> values, String start) {

    /** The value in force on the date (yyyy-MM-dd): the one with the latest from-date on or before
     *  it (none: from the beginning of time), else the starting value; null when blank or none. */
    public String on(String date) {
        Setting found = null;
        for (Setting s : values) {
            if (s.from() != null && s.from().compareTo(date) > 0) continue;
            if (found == null || nz(found.from()).compareTo(nz(s.from())) < 0) found = s;
        }
        if (found == null) return start;
        return found.value().isEmpty() ? null : found.value();
    }

    private static String nz(String from) {
        return from == null ? "" : from;
    }
}
EOF
